const body = $input.first().json.body;
const topic = body.topic || '未指定主题';
const style = body.style || '现代简约';
const numScenes = body.num_scenes || 5;
const duration = body.duration || 60;

const systemPrompt = `你是一个专业的视频分镜师。你必须只返回有效的JSON，不要有任何其他文字。`;

const userPrompt = `根据以下信息生成分镜脚本：

- 主题: ${topic}
- 风格: ${style}
- 分镜数量: ${numScenes}
- 视频总时长: ${duration}秒

输出JSON格式(严格按此格式，不要包装在markdown代码块中):
{
  "scenes": [
    {
      "index": 1,
      "description": "场景中文描述",
      "prompt": "英文图片生成提示词，详细描述画面，适合AI文生图",
      "narration": "中文配音文本，自然口语化",
      "duration": 12
    }
  ]
}

要求：
1. prompt必须是英文、详细描述画面细节、灯光、构图、色彩等
2. narration用中文，自然口语化
3. 每个场景至少5秒
4. 场景之间要有叙事连贯性
5. 总时长尽量接近${duration}秒`;

return [{
  json: {
    body: {
      model: 'agnes-2.0-flash',
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: userPrompt }
      ],
      response_format: { type: 'json_object' },
      temperature: 0.7
    },
    originalInput: body
  }
}];

const response = $input.first().json;

const content = response?.choices?.[0]?.message?.content;
if (!content) {
  throw new Error('AI 返回内容为空: ' + JSON.stringify(response).substring(0, 500));
}

let cleanContent = content.trim();
if (cleanContent.startsWith('```')) {
  cleanContent = cleanContent.replace(/^```(?:json)?\n?/, '').replace(/\n?```$/, '');
}

let parsed;
try {
  parsed = JSON.parse(cleanContent);
} catch (e) {
  throw new Error('无法解析 AI 返回的 JSON: ' + cleanContent.substring(0, 300));
}

const scenes = (parsed.scenes || []).map((scene, i) => ({
  index: scene.index || (i + 1),
  description: scene.description || '',
  prompt: scene.prompt || '',
  narration: scene.narration || '',
  duration: Math.max(5, scene.duration || 10)
}));

return [{
  json: {
    success: true,
    scenes: scenes,
    totalScenes: scenes.length,
    totalDuration: scenes.reduce((sum, s) => sum + s.duration, 0),
    generatedAt: new Date().toISOString()
  }
}];
